create or replace function pdf_template_document_data(p_type text,p_number text)returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare x jsonb;begin
 if p_type='FAC_VEN'then select jsonb_build_object('company',jsonb_build_object('name',s.name,'tax_id',coalesce(s.tax_id,''),'logo_url',coalesce(s.logo_url,''),'address',coalesce(s.address,''),'phone',coalesce(s.phone,''),'email',coalesce(s.email,'')),'entity',jsonb_build_object('name',c.company_name,'tax_id',coalesce(c.tax_id,'')),'document',jsonb_build_object('title','Factura de venta','number',i.invoice_number,'issue_date',i.invoice_date,'due_date',i.due_date,'currency_symbol',cu.currency_code),'totals',jsonb_build_object('subtotal',i.total_amount-coalesce((select sum(tax_amount)from sales_invoice_line where invoice_id=i.invoice_id),0),'discount_total',0,'tax_total',coalesce((select sum(tax_amount)from sales_invoice_line where invoice_id=i.invoice_id),0),'grand_total',i.total_amount,'amount_in_words',''),'fiscal',jsonb_build_object('electronic_key','','qr_code',''),'items',coalesce((select jsonb_agg(jsonb_build_object('code',coalesce(p.item_code,''),'description',coalesce(l.note,p.display_name,''),'quantity',l.quantity,'unit_price',l.unit_price,'discount',0,'tax_rate',l.tax_rate,'subtotal',l.amount)order by l.line_id)from sales_invoice_line l left join products p using(product_id)where l.invoice_id=i.invoice_id),'[]'))into x from invoice i join subsidiaries s using(subsidiary_id)join customers c using(customer_id)join currencies cu using(currency_id)where i.subsidiary_id=active_subsidiary_id()and i.invoice_number=p_number limit 1;
 elsif p_type='ORD_COM'then select jsonb_build_object('company',jsonb_build_object('name',s.name,'tax_id',coalesce(s.tax_id,''),'logo_url',coalesce(s.logo_url,'')),'entity',jsonb_build_object('name',coalesce(v.company_name,''),'tax_id',coalesce(v.tax_id,'')),'document',jsonb_build_object('title','Orden de compra','number',d.document_number,'issue_date',d.document_date,'due_date',d.valid_until,'currency_symbol',cu.currency_code),'totals',jsonb_build_object('subtotal',d.total_amount-coalesce((select sum(tax_amount)from purchase_document_line where document_id=d.document_id),0),'discount_total',0,'tax_total',coalesce((select sum(tax_amount)from purchase_document_line where document_id=d.document_id),0),'grand_total',d.total_amount,'amount_in_words',''),'fiscal',jsonb_build_object('electronic_key','','qr_code',''),'items',coalesce((select jsonb_agg(jsonb_build_object('code',coalesce(p.item_code,''),'description',coalesce(l.description,p.display_name,''),'quantity',l.quantity,'unit_price',l.unit_cost,'discount',0,'tax_rate',l.tax_rate,'subtotal',l.quantity*l.unit_cost)order by l.line_number)from purchase_document_line l left join products p using(product_id)where l.document_id=d.document_id),'[]'))into x from purchase_document d join subsidiaries s using(subsidiary_id)left join suppliers v using(supplier_id)join currencies cu using(currency_id)where d.subsidiary_id=active_subsidiary_id()and d.document_type='ORDER'and d.document_number=p_number limit 1;
 elsif p_type in('PED_VEN','COT_VEN')then select jsonb_build_object('company',jsonb_build_object('name',s.name,'tax_id',coalesce(s.tax_id,''),'logo_url',coalesce(s.logo_url,'')),'entity',jsonb_build_object('name',c.company_name,'tax_id',coalesce(c.tax_id,'')),'document',jsonb_build_object('title',case when d.document_type='ORDER'then'Orden de venta'else'Cotización'end,'number',d.document_number,'issue_date',d.document_date,'due_date',d.valid_until,'currency_symbol',cu.currency_code),'totals',jsonb_build_object('subtotal',d.total_amount-coalesce((select sum(tax_amount)from sales_document_line where document_id=d.document_id),0),'discount_total',0,'tax_total',coalesce((select sum(tax_amount)from sales_document_line where document_id=d.document_id),0),'grand_total',d.total_amount,'amount_in_words',''),'fiscal',jsonb_build_object('electronic_key','','qr_code',''),'items',coalesce((select jsonb_agg(jsonb_build_object('code',coalesce(p.item_code,''),'description',coalesce(l.description,p.display_name,''),'quantity',l.quantity,'unit_price',l.unit_price,'discount',0,'tax_rate',l.tax_rate,'subtotal',l.quantity*l.unit_price)order by l.line_number)from sales_document_line l left join products p using(product_id)where l.document_id=d.document_id),'[]'))into x from sales_document d join subsidiaries s using(subsidiary_id)join customers c using(customer_id)join currencies cu using(currency_id)where d.subsidiary_id=active_subsidiary_id()and d.document_type=case when p_type='PED_VEN'then'ORDER'else'QUOTE'end and d.document_number=p_number limit 1;
 end if;if x is null then raise exception'No se encontró un documento % con número % en la subsidiaria activa.',p_type,p_number;end if;return x;end$$;
grant execute on function pdf_template_document_data(text,text)to authenticated;
notify pgrst,'reload schema';
